ue="{{$order?->expected_date?->format('Y-m-d')}}"></div><div class="col-12"><label class="form-label">หมายเหตุ</label><textarea name="description" class="form-control" rows="2">{{$order?->description}}</textarea></div></div></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between mb-3"><div><h2 class="h5 mb-1">รายการสั่งซื้อ</h2><small class="text-secondary">ราคาจะบันทึกที่ PO ไม่ใช่ PR และระบบคำนวณยอดรวมจากจำนวน × ราคาต่อหน่วย</small></div>@if(!$fromPr)<button type="button" id="po-add-line" class="btn btn-sm btn-app-soft">เพิ่มบรรทัด</button>@endif</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th style="min-width:220px">สินค้า</th><th style="min-width:200px">รายละเอียด</th><th style="min-width:140px">หน่วย</th><th style="min-width:130px">จำนวน</th><th style="min-width:150px">ราคา/หน่วย</th><th class="text-end" style="min-width:120px">รวม</th>@if(!$fromPr)<th></th>@endif</tr></thead><tbody id="po-lines">@foreach($rows as $i=>$row)<tr class="po-line"><td><select name="lines[{{$i}}][item_id]" class="form-select po-item" @disabled($fromPr)><option value="">ไม่ผูกสินค้า</option>@if(!empty($row['item_id'])) @php($item=\App\Modules\Wms\Models\Item::find($row['item_id'])) @if($item)<option value="{{$item->id}}" selected>{{$item->code}} · {{$item->name}}</option>@endif @endif</select>@if($fromPr)<input type="hidden" name="lines[{{$i}}][item_id]" value="{{$row['item_id']}}"><input type="hidden" name="lines[{{$i}}][purchase_requisition_line_id]" value="{{$row['purchase_requisition_line_id']}}">@endif</td><td><input name="lines[{{$i}}][description]" class="form-control" value="{{$row['description']}}" required></td><td><select name="lines[{{$i}}][uom_id]" class="form-select po-uom" @disabled($fromPr)><option value="">เลือกหน่วย</option>@if(!empty($row['uom_id'])) @php($uom=\App\Modules\Wms\Models\Uom::find($row['uom_id'])) @if($uom)<option value="{{$uom->id}}" selected>{{$uom->code}} · {{$uom->name}}</option>@endif @endif</select>@if($fromPr)<input type="hidden" name="lines[{{$i}}][uom_id]" value="{{$row['uom_id']}}">@endif</td><td><input name="lines[{{$i}}][quantity]" class="form-control text-end" type="number" step="0.0001" min="0.0001" value="{{$row['quantity']}}" @disabled($fromPr) required></td><td><input name="lines[{{$i}}][unit_price]" class="form-control text-end js-po-price" type="number" step="0.0001" min="0" value="{{$row['unit_price']}}" required></td><td class="text-end js-po-total">0.00</td>@if(!$fromPr)<td><button class="btn btn-sm btn-outline-danger js-remove-po-line" type="button">ลบ</button></td>@endif</tr>@endforeach</tbody><tfoot><tr><th colspan="5" class="text-end">รวม</th><th class="text-end" id="po-subtotal">0.00</th>@if(!$fromPr)<th></th>@endif</tr></tfoot></table></div><div class="mt-4"><button class="btn btn-dark" type="submit">บันทึกร่าง PO</button> <a class="btn btn-outline-secondary" href="{{route($moduleRoutePrefix.'.purchase-orders.index')}}">ยกเลิก</a></div></div></div></form></div>
