@push('scripts')<script>$(function(){var l=$('#po-lines'),itemUrl='{{route($moduleRoutePrefix.'.purchase-documents.item-options')}}',uomUrl='{{route($moduleRoutePrefix.'.purchase-documents.uom-options')}}';function select(s,url,p){s.select2({width:'100%',placeholder:p,ajax:{url:url,dataType:'json',delay:250,data:function(x){return{q:x.term||'',page:x.page||1};},processResults:function(d){return d;}}});}function init(r){if(!r.find('.po-item').prop('disabled'))select(r.find('.po-item'),itemUrl,'ค้นหาสินค้า');if(!r.find('.po-uom').prop('disabled'))select(r.find('.po-uom'),uomUrl,'เลือกหน่วย');}select($('#po-supplier'),'{{route($moduleRoutePrefix.'.purchase-documents.supplier-options')}}','ค้นหา Supplier');l.find('tr').each(function(){init($(this));});function money(n){return Number.isFinite(n)?n.toFixed(2):'0.00';}function totals(){var sum=0;l.find('tr').each(function(){var q=parseFloat($(this).find('[name$="[quantity]"]').val())||0,p=parseFloat($(this).find('.js-po-price').val())||0,t=q*p;sum+=t;$(this).find('.js-po-total').text(money(t));});$('#po-subtotal').text(money(sum));}l.on('input','.js-po-price,[name$="[quantity]"]',totals);totals();$('#po-add-line').on('click',function(){var n=l.children().length,r=$('<tr class="po-line"><td><select name="lines['+n+'][item_id]" class="form-select po-item"><option value="">ไม่ผูกสินค้า</option></select></td><td><input name="lines['+n+'][description]" class="form-control" required></td><td><select name="lines['+n+'][uom_id]" class="form-select po-uom"><option value="">เลือกหน่วย</option></select></td><td><input name="lines['+n+'][quantity]" class="form-control text-end" type="number" step="0.0001" min="0.0001" value="1" required></td><td><input name="lines['+n+'][unit_price]" class="form-control text-end js-po-price" type="number" step="0.0001" min="0" value="0" required></td><td class="text-end js-po-total">0.00</td><td><button class="btn btn-sm btn-outline-danger js-remove-po-line" type="button">ลบ</button></td></tr>');l.append(r);init(r);});l.on('click','.js-remove-po-line',function(){if(l.children().length>1){$(this).closest('tr').remove();totals();}});window.erpAjaxForm({form:'#purchase-order-form',redirect:true});});</script>@endpush
@push('scripts')<script>$(function(){var f=$('#purchase-order-form');f.on('submit',function(){f.find('input:disabled').each(function(){var i=$(this),n=i.attr('name');if(n&&n.indexOf('[quantity]')!==-1&&!f.find('input[type="hidden"][name="'+n+'"]').length)$('<input>',{type:'hidden',name:n,value:i.val()}).appendTo(f);});});});</script>@endpush
